// 1. Setup Data & Time Context
const finalJson = $('When Executed by Another Workflow').first().json;
const aiRawOutput = $input.first().json.output;
const currentTimeStr = finalJson.sensors.time_of_day; // e.g., "14:00"

// 2. Extract AI Output safely (handles conversational text before "Output:")
let dataString = aiRawOutput;
if (aiRawOutput.includes("Output:")) {
  const splits = aiRawOutput.split("Output:");
  dataString = splits[splits.length - 1].trim(); 
}

// 3. Parse Key-Value Pairs
const pairs = dataString.split(/\s+/); // Splits by any space or newline

pairs.forEach(pair => {
  // Find the FIRST colon only. This prevents splitting "14:00" into "14" and "00"
  const colonIndex = pair.indexOf(":");
  if (colonIndex === -1) return; 

  const keyPath = pair.substring(0, colonIndex); // e.g., "pump.timer.execute_until"
  const value = pair.substring(colonIndex + 1);  // e.g., "14:10", "true", or "10"

  const parts = keyPath.split(".");
  let finalValue = value;

  // Type Conversion
  if (value === "true") finalValue = true;
  else if (value === "false") finalValue = false;
  else if (value === "null") finalValue = null;
  else if (!isNaN(value) && value !== "") finalValue = Number(value); // Converts purely numeric strings

  // Safely inject into JSON structure
  if (parts.length === 3 && finalJson.actuators[parts[0]] && finalJson.actuators[parts[0]][parts[1]]) {
    finalJson.actuators[parts[0]][parts[1]][parts[2]] = finalValue;
  }
  if (parts.length === 2 && finalJson.actuators[parts[0]]) {
    finalJson.actuators[parts[0]][parts[1]] = finalValue;
  }
});

// 4. Time Math Verification Helpers
const timeToMins = (timeStr) => {
  if (!timeStr || typeof timeStr !== 'string' || !timeStr.includes(':')) return -1;
  const [h, m] = timeStr.split(':').map(Number);
  return (h * 60) + m;
};

const minsToTime = (mins) => {
  const h = Math.floor(mins / 60) % 24;
  const m = mins % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const currentMins = timeToMins(currentTimeStr);

// 5. Verify, Correct, and Classify Actuators
['pump', 'fan'].forEach(device => {
  const act = finalJson.actuators[device];

  // --- A. VALIDATE DELAY (execute_at) ---
  if (act.delay.active === false) {
    // If not delayed, it MUST execute right now. Overwrite AI if wrong.
    if (act.delay.execute_at !== currentTimeStr) {
      act.delay.execute_at = currentTimeStr; 
    }
  } else {
    // If delayed, verify the AI didn't pick a time in the past (time travel) or use null
    const delayMins = timeToMins(act.delay.execute_at);
    if (delayMins <= currentMins || delayMins === -1) {
      // Correct it by pushing it 60 minutes into the future dynamically
      act.delay.execute_at = minsToTime(currentMins + 60); 
    }
  }

  // --- B. VALIDATE TIMER (execute_until) ---
  if (act.timer.active === true) {
    // Calculate mathematically what the end time SHOULD be
    const startMins = timeToMins(act.delay.execute_at);
    const expectedEndStr = minsToTime(startMins + act.timer.duration_minutes);

    // If the AI's math is wrong (or null), overwrite it with the true calculated time
    if (act.timer.execute_until !== expectedEndStr) {
      act.timer.execute_until = expectedEndStr; 
    }
  } else {
    // Clean up data if timer is inactive
    act.timer.execute_until = null;
    act.timer.duration_minutes = 0;
  }

  // --- C. APPLY CLASSIFICATION ---
  if (act.physical_state === "on") {
    act.classification = "WORKING";
  } else if (act.physical_state === "off" && act.delay.active === true) {
    act.classification = "PENDING";
  } else {
    act.classification = "FREE";
  }
});

// 6. Output the perfectly formatted JSON
return [{ json: finalJson }];
